                  <q-icon
                    @click="applyFuzzySearch(fuzzySearchField)"
                    name="search"
                    data-cy="search"
                    class="q-pb-md cursor-pointer"
                  />
                </template>
              </q-input>
            </div>

            <div class="q-pa-md">
              <q-table
                :rows="tableRows"
                :columns="tableColumns"
                row-key="id"
                :no-data-label="$t('no_record_found')"
                selection="single"
                v-model:selected="selectedRow"
                table-header-class="highlighted-back"
                :loading="loading"
                hide-bottom
                style="overflow: scroll; height: 400px"
                :rows-per-page-options="[0]"
                @selection="onRowSelection"
              >
                <template v-slot:header="props">
                  <q-tr :props="props">
                    <q-th
                      v-for="col in props.cols"
                      :key="col.name"
                      :props="props"
                    >
                      {{ col.label }}
                    </q-th>
                  </q-tr>
                </template>
                <template v-slot:body="props">
                  <q-tr
                    class="cursor-pointer"
                    :props="props"
                    @click="props.selected = !props.selected"
                  >
                    <q-td
                      v-for="col in props.cols"
                      :key="col.name"
                      :props="props"
                    >
                      {{ col.value }}
                    </q-td>
                  </q-tr>
                </template>
              </q-table>

              <!-- <div class="q-mt-md">
              Selected: {{ JSON.stringify(selected) }}
            </div> -->
              <div class="q-mt-md full-width text-center">
                <q-btn
                  color="primary"
                  class="q-mr-sm"
                  data-cy="setvatfield"
                  :label="$t('proceed')"
                  @click="setVatField()"
                  :disable="disableSelectionButton"
                />
                <q-btn :label="$t('cancel')" v-close-popup />
              </div>
            </div>
          </q-card-section>
        </q-card>
      </q-dialog>
    </div>
    <!-- FUZZY DIALOG END -->
  </template>

  <template v-if="is_sep_view">
    <Loader />
  </template>
</template>

<script lang="ts">

import axios from 'axios';
import Loader from './Loader.vue';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { api, getAuthorizationToken, getMediVendorsListAPI } from 'pages/APIs';
import { useQuasar, LocalStorage, debounce, SessionStorage } from 'quasar';
import type { QTableColumn } from 'quasar';
import MediMultiSelectInputImage from 'src/components/MediMultiSelectInputImage.vue';
import medi_fields_def from 'src/utils/medi_fields_def';
import { ApiExceptions } from 'src/exceptions/index';
import amountConversionHelper from 'src/utils/amountConversionHelper';
import { isUndefinedOrNull, isObjectEmtpy, objLen } from 'src/utils/general';
import { readOnlyDocStatus } from 'src/constants';
import autoTesting from 'src/components/autoTesting.vue';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { documentDetailApiService } from 'src/services';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import { notify } from 'src/components/notifications/notify';

const $ = document.querySelector.bind(document);
let fuzzyMap = new Map();

export default defineComponent({
  el: '#app',
  mixins: [
    helperMixin, medi_fields_def,
    amountConversionHelper,
    displayFieldLabel,
  ],
  props: {
    data: [] as any,
    renderOpenWindoIcon: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    
    Loader,
    MediMultiSelectInputImage,
    autoTesting,
  },
  watch: {
    async data(val) {
      this.updateLocalData(this.data);
      await this.makeModel();
    },
  },
  data() {
    return {
      docId: '',
      imageHeight: 0,
      imageWidth: 0,
      itemsData: {} as dynamicObj,
      conversionFields: [] as any,
      articleNumberFields: [] as any,
      debounceArticleSearchFunc: {} as any,
    };
  },
  mounted: function () {
    this.docId = this.$route.params.id as string;
    this.isViewSeparateComponenet();
    this.init();
    window.addEventListener('resize', this.windowResize);
    document.addEventListener('model_updated', this.updateModelAttribute);
    document.addEventListener('reload_tables', this.reloadTable);

    this.debounceArticleSearchFunc = debounce(() => {
      this.calculateArticleNumber();
    }, 1000);
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener('model_updated', this.updateModelAttribute);
    document.removeEventListener('reload_tables', this.reloadTable);
  },
  methods: {
    reloadTable() {
      this.renderKey++;
    },
    async init() {
      if (this.is_sep_view) {
        let cached_api_data = LocalStorage.has('fields_sep_comp')
          ? (LocalStorage.getItem('fields_sep_comp') as dynamicObj)
          : null;
        if (cached_api_data != null && cached_api_data.doc_id == this.docId) {
          LocalStorage.remove('fields_sep_comp');
          this.updateLocalData(cached_api_data);
        } else {
          await this.getInvoiceDataByDocId(this.docId);
        }
      } else {
        this.updateLocalData(this.data);
      }
      if (readOnlyDocStatus.includes(this.apiData.status)) {
        this.isReadOnly = true;
      }

      this.setConversionFields();
      this.setArticleNumberRelatedFields();
      await this.makeModel();

      if (!this.isModelReady()) {
        notify.error(
          'Document does not have layout. Please contact administrator',
        );
        return;
      }
      let imageElm = $('#image_container2') as HTMLElement;
      this.imageWidth2 = imageElm.offsetWidth;
      this.imageHeight2 = imageElm.offsetHeight;
      //  logInfo('init',  this.imageWidth2, this.imageHeight2)
      this.image2 = 'images/medi.svg';
      this.setFuzzyTableColumns();
      this.loadSelectedAreasFields();
    },
    // TODO::Permission  acls needs to be applied here
    async getInvoiceDataByDocId(docId: string) {
      try {
        const data = {
          doc_id: docId,
        };
        const response = await documentDetailApiService.getById(data);
        if (!response.doc_id) {
          notify.error(this.$t('INVALID_DOCUMENT'));
          return;
        }
        this.updateLocalData(response);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    updateLocalData(data: any) {
      this.apiData = data;
    },
    makeModel() {
      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.apiData !== undefined) {
          this.apiData.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
          });
          let layout = [] as dynamicObj[];
          layout = this.apiData.layout.groups;
          layout.forEach((group: any, index: any) => {
            group.rows.forEach((row: any, index: any) => {
              row.forEach((fieldDef: any, index: any) => {
                let field_name = fieldDef.field_name;
                let field_model = data[field_name];

                if (field_model) {
                  this.setColor(field_model, fieldDef);
                } else {
                  field_model = this.createEmptyField(
                    field_name,
                    fieldDef.input_type,
                  );
                }
                this.cleanCheckboxValue(field_model, fieldDef.input_type);

                this.model[field_name] = field_model;
                this.fieldsDef[field_name] = fieldDef;
              });
            });
          });
        }
        resolve('done');
      });
    },
    cleanCheckboxValue(field_model: any, type: string) {
      if (type != 'checkbox') {
        return;
      }

      if (
        field_model.formatted_value == 'true' ||
        field_model.formatted_value == true ||
        field_model.formatted_value == 'Y'
      ) {
        field_model.formatted_value = true;
      } else {
        field_model.formatted_value = false;
      }
    },
    setColor(field_model: any, fieldDef: any) {
      if (field_model.extraction_method == 'MD') {
        fieldDef.color = 'extraction_method-border-left';
      } else if (field_model.is_valid) {
        fieldDef.color = 'success-border-left';
      } else {
        fieldDef.color = 'error-border-left';
      }
    },
    setConversionFields() {
      this.conversionFields = this.getConversionFields();
    },
    setArticleNumberRelatedFields() {
      this.articleNumberFields = this.getArticleNumberfields();
    },
    getField(name: string) {
      let foundField = {} as dynamicObj;
      if (this.apiData !== undefined) {
        for (const key in this.apiData.fields) {
          let field = this.apiData.fields[key];
          if (field.name == name) {
            foundField = field;
            break;
          }
        }
      }

      return foundField;
    },
    createEmptyField(name: string, type: string) {
      let value = type == 'checkbox' ? false : '';
      return {
        confidence: 0,
        name: name,
        value: value,
        formatted_value: value,
        content: value,
      };
    },
    loadSelectedAreasFields() {
      let tableData = {} as dynamicObj;
      let fieldsDef = this.getSAFieldsDef();
      let fields = this.getSAFields();
      let table_areas = [] as dynamicObj[];

      Array.from(fields).forEach((field_name: any) => {
        if (fieldsDef.hasOwnProperty(field_name)) {
          table_areas.push(
            Object.assign({ name: field_name }, fieldsDef[field_name]),
          );
        }
      });

      tableData = { columns: [], table_areas: table_areas };
      let tableStr = JSON.stringify(tableData);
      SessionStorage.set('table_data', tableStr);
      this.tableAreasStr = tableStr;
      this.isSelectedAreaFieldsReady = true;
      //logInfo('loadSelectedAreasFields 1',tableData, this.tableAreasStr)
    },
    persistTableAreas() {
      this.saveMediImageFields();
    },
    windowResize() {
      this.persistTableAreas();
      //logInfo('windowResize 1')

      // this.$forceUpdate();

      setTimeout(() => {
        let imageElm = $('#image_container2') as HTMLElement;
        this.imageWidth2 = imageElm.offsetWidth;
        this.imageHeight2 = imageElm.offsetHeight;
        //logInfo('windowResize setTimeout',  this.imageWidth2, this.imageHeight2)
        this.loadSelectedAreasFields();
      }, 0);
    },
    saveMediImageFields() {
      let tableData = {} as dynamicObj;
      if (
        SessionStorage.has('table_data') &&
        SessionStorage.getItem('table_data') != null &&
        SessionStorage.getItem('table_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_data');
        tableData = JSON.parse(tableDataStr as string);
      } else {
        tableData = { columns: [], table_areas: [] };
      }
      // this.updateExtractionDataForSave('medi_fields', tableData);
    },
    // TODO::Permission  acls needs to be applied here
    async saveData() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.saveMediImageFields();
        let data: any = this.apiData;
        this.showLoading();
        if (data.hasOwnProperty('table_data_copy')) {
          delete data['table_data_copy'];
        }
        // let data : string = JSON.stringify(this.jsonData);

        let formData = new FormData();
        formData.append('data', JSON.stringify(data));

        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.post(api.save_document + this.docId, formData, {
          headers: {
            Authorization: token,
          },
        });

        this.hideLoading();
        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(this.$t('MSG_SAVE'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    // TODO::Permission  acls needs to be applied here
    async exportData() {
      if (this.isReadOnly) {
        return;
      }
      try {
        let response: any;
        let data: any = this.apiData;
        this.showLoading();
        if (data.hasOwnProperty('table_data_copy')) {
          delete data['table_data_copy'];
        }
        let formData = new FormData();
        formData.append('data', JSON.stringify(data));

        response = await documentDetailApiService.validate_and_export(
          this.docId,
          formData,
        );

        if (response.success === true) {
          this.hideLoading();
          this.$router.push('/success').catch();
        } else {
          let messages: [] = response.validation_error_codes;

          if (messages) {
            messages.forEach((messageStr: string) => {
              let temp = messageStr.split(':');
              let label = this.displayFieldLabel(
                this.fieldsDef[temp[0]],
              );
              notify.error(
                label + ' ' + this.$t(temp[1]),
              );
            });
          } else {
            notify.error(response.message);
            this.hideLoading();
          }

          this.$emit('setApiData', response.data);
          this.hideLoading();
        }
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    isModelReady() {
      return objLen(this.model) !== 0;
    },
    isSelectedAreaDataReady() {
      return this.isSelectedAreaFieldsReady;
    },
    getConfidence(confidence: number) {
      if (confidence) {
        return confidence < 1
          ? (+confidence.toFixed(2) * 100).toFixed(0)
          : +confidence.toFixed(2);
      }
      return '';
    },
    getLowerConfidence(field: any) {
      if (field.confidence && field.score) {
        let converted_confidence =
          field.confidence < 1
            ? (field.confidence.toFixed(2) * 100).toFixed(0)
            : (field.confidence.toFixed(2) as number);
        let converted_score =
          field.score <= 1
            ? (field.score.toFixed(2) * 100).toFixed(0)
            : (field.score.toFixed(2) as number);
        converted_confidence = Number(converted_confidence);
        converted_score = Math.floor(Number(converted_score));
        return converted_confidence < converted_score
          ? converted_confidence
          : converted_score;
      } else if (field.confidence) {
        return (
          field.confidence < 1
            ? (field.confidence.toFixed(2) * 100).toFixed(0)
            : field.confidence.toFixed(2)
        ) as number;
      }
      return null;
    },
    openComponentInSaparateWindow() {
      LocalStorage.set('fields_sep_comp', this.apiData);
      let route = this.$router.resolve({
        path: '/fields_sep_comp/' + this.docId,
      });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1500,height=1000',
      );
    },
    isViewSeparateComponenet() {
      if (this.$route.fullPath.match(/fields_sep_comp/g)) {
        this.is_sep_view = true;
      }
    },
    setCheckboxBackgroupColor(field_name: string) {
      let field = this.fieldsDef[field_name];
      let bg_color = '';
      if (field.is_readonly == true) {
        bg_color = ' bg-disable ';
      } else if (this.model[field_name].formatted_value == true) {
        bg_color = ' color-primary ';
      }
      return bg_color;
    },
    async applyFuzzySearch(text: string) {
      this.fuzzySearchField = text;
      this.showLoading();

      let response: any;
      try {
        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(getMediVendorsListAPI(text)),
          {
            headers: {
              Authorization: token,
            },
          },
        );
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      }
      this.tableRows = [];

      Array.from(response.data).forEach((tableRow: any, index: any) => {
        let newRow: dynamicObj = {};
        newRow['id'] = tableRow.id;
        fuzzyMap.forEach((value: Map<string, string>, key: string) => {
          value.forEach((supplier_field_name: string, field_name: string) => {
            newRow[supplier_field_name] = tableRow[supplier_field_name];
          });
        });
        this.tableRows.push(newRow);
      });
      this.fuzzyDialog = true;
      this.hideLoading();
      this.$forceUpdate();
    },
    populateFuzzyData(response: string) {
      let jsonResponse = JSON.parse(response);
      let fields_to_update = [] as string[];
      fuzzyMap.forEach((value: Map<string, string>, key: string) => {
        value.forEach((responseKey: string, field: string) => {
          if (jsonResponse.hasOwnProperty(responseKey)) {
            this.model[field].formatted_value = jsonResponse[responseKey];
            this.model[field].value = jsonResponse[responseKey];
            this.model[field].content = jsonResponse[responseKey];
            this.fieldsDef[field].color = 'extraction_method-border-left';
            this.model[field].extraction_method = 'MD';
            fields_to_update.push(field);
          }
        });
      });

      if (fields_to_update.length > 0) {
        this.updateImportJson(fields_to_update, 'MD');
      }
    },
    onRowSelection(evt: any) {
      if (evt.added) {
        this.disableSelectionButton = false;
      } else {
        this.disableSelectionButton = true;
      }
    },
    setVatField() {
      let row = JSON.parse(JSON.stringify(this.selectedRow));
      this.populateFuzzyData(JSON.stringify(row[0]));

      this.fuzzyDialog = false;
      this.selectedRow = [];
      this.disableSelectionButton = true;
      this.$forceUpdate();
    },
    updateModelAttribute(e: any) {
      if (!e.detail || !e.detail.field_name) {
        return;
      }
      this.updateImportJson([e.detail.field_name]);
    },
    inputValueChanges(field_name: string) {
      setTimeout(() => {
        this.model[field_name].value = this.model[field_name].formatted_value;
        this.model[field_name].content = this.model[field_name].formatted_value;
        this.updateImportJson([field_name]);
        if (this.articleNumberFields.includes(field_name)) {
          this.debounceArticleSearchFunc();
        }
      }, 0);
    },
    updateImportJson(fields: string[], extractionMethod?: string) {
      let found_fields = [] as string[];
      this.apiData.fields.forEach((value: any, index: any) => {
        let field_name = value.name;

        if (fields.includes(field_name)) {
          found_fields.push(field_name);

          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign({}, value);
          }

          value.is_valid = true;
          value.is_validated = true;
          let field = this.model[field_name];
          let fieldDef = this.fieldsDef[field_name];
          value.formatted_value = field.formatted_value;
          value.value = field.value;
          value.content = field.content;
          if (!(field.hasOwnProperty('api_save') && field.api_save)) {
            value.value = field.formatted_value;
            value.content = field.formatted_value;
          }

          if (
            !(field.hasOwnProperty('api_save') && field.api_save) &&
            this.conversionFields.includes(field.name) &&
            this.apiData.doc_locale == 'en_DE'
          ) {
            value.value = this.convertToUSValue(value.value);
          }

          if (field.hasOwnProperty('extraction_method')) {
            value.extraction_method = field.extraction_method;
          }

          value.color = 'success-border-left';
          if (value.extraction_method == 'MD') {
            value.color = 'extraction_method-border-left';
          }

          this.model[field_name] = value;
          fieldDef.color = value.color;
        }
      });

      fields.forEach((field_name: any, index: any) => {
        // field not found
        if (!found_fields.includes(field_name)) {
          this.apiData.fields.push(this.model[field_name]);
          this.apiData.fields[this.apiData.fields.length - 1].name = field_name;
          this.apiData.fields[this.apiData.fields.length - 1].content =
            this.model[field_name].content;
          this.apiData.fields[this.apiData.fields.length - 1].formatted_value =
            this.model[field_name].formatted_value;
          this.apiData.fields[this.apiData.fields.length - 1].value =
            this.model[field_name].value;
          this.apiData.fields[this.apiData.fields.length - 1].validation_code =
            '';
          this.apiData.fields[
            this.apiData.fields.length - 1
          ].extraction_method = extractionMethod;
          this.apiData.fields[this.apiData.fields.length - 1].is_validated =
            true;
          this.apiData.fields[this.apiData.fields.length - 1].is_valid = true;
          this.model[field_name] =
            this.apiData.fields[this.apiData.fields.length - 1];
          this.fieldsDef[field_name].color = 'success-border-left';
          if (extractionMethod == 'MD') {
            this.fieldsDef[field_name].color = 'extraction_method-border-left';
          }
        }
      });
    },
    setFuzzyTableColumns() {
      this.tableColumns = [];
      fuzzyMap.forEach((value: Map<string, string>, key: string) => {
        value.forEach((supplier_field_name: string, field_name: string) => {
          let label = this.displayFieldLabel(this.fieldsDef[field_name]);
          this.tableColumns.push({
            name: field_name,
            label: label,
            field: supplier_field_name,
            align: 'left',
          });
        });
      });
    },
    async calculateArticleNumber() {
      this.showLoading();
      let response: any;
      try {
        let formData = new FormData();
        formData.append('doc_data', JSON.stringify(this.apiData));
        let token: string = await getAuthorizationToken();
        response = await axios.post(api.get_medi_item_number, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw response;
        } else {
          let field_name = 'article_number';
          this.model[field_name].formatted_value = response.data.code;
          this.inputValueChanges(field_name);
        }

        this.hideLoading();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.hideLoading();
      }
    },
    async setArticleFieldsBySearch() {
      try {
        let field_name = 'article_number';
        if (
          !(
            this.model[field_name].formatted_value &&
            this.model[field_name].formatted_value !== ''
          )
        ) {
          notify.error(this.$t('artikle_number_required'));
          return;
        }
        let response: any;
        this.showLoading();
        let formData = new FormData();
        formData.append('item_number', this.model[field_name].formatted_value);
        let token: string = await getAuthorizationToken();
        response = await axios.post(
          api.get_medi_item_number_fields_map,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw response;
        } else {
          this.setArticleFieldsValues(response.data.data);
          // logInfo(response.data.data,'article fields')
        }

        this.hideLoading();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.hideLoading();
      }
    },
    setArticleFieldsValues(fieldsData: any) {
      let fields_to_update = [] as string[];

      for (const field_name of Object.keys(fieldsData)) {
        let field_value = fieldsData[field_name];
        this.model[field_name].formatted_value = field_value;
        fields_to_update.push(field_name);
      }

      let difference = this.articleNumberFields.filter(
        (x: string) => !fields_to_update.includes(x),
      );
      difference.forEach((field_name: any, index: any) => {
        let fieldDef = this.fieldsDef[field_name];
        if (fieldDef.input_type == 'checkbox') {
          this.model[field_name].formatted_value = false;
        } else {
          this.model[field_name].formatted_value = '';
        }
        fields_to_update.push(field_name);
      });

      setTimeout(() => {
        fields_to_update.forEach((field_name: any, index: any) => {
          this.model[field_name].value = this.model[field_name].formatted_value;
          this.model[field_name].content =
            this.model[field_name].formatted_value;
        });
        if (fields_to_update.length > 0) {
          this.updateImportJson(fields_to_update);
        }
      }, 0);
    },
    fieldKeyupEventHandler(event: any) {
      if (this.isReadOnly === true) {
        return;
      }
      if (event.key === 'Enter') {
        let name = event.target.dataset.name;
        if (name) {
          this.updateModelAttribute({ detail: { field_name: name } });
        }
      }
    },
    handleSingleSelection(field_name: string, new_value: any) {
      let fields_to_update = [
        'stuck_checkbox',
        'paar_checkbox',
        'hose_checkbox',
      ];
      if (new_value === true) {
        fields_to_update.forEach((fieldName: any, index: any) => {
          if (fieldName !== field_name) {
            this.model[fieldName].formatted_value = false;
            this.model[fieldName].value = false;
          }
        });
      }
      this.model[field_name].formatted_value = new_value;
      this.model[field_name].value = new_value;
      this.model[field_name].content = new_value;
      this.updateImportJson(fields_to_update);
    },
  },
  setup() {
    let data: any = [];

    return {
      apiData: ref(data),
      tableAreasStr: ref(''),
      model: ref({} as dynamicObj),
      fieldsDef: ref({} as dynamicObj),
      image2: ref(''),
      imageHeight2: ref(0),
      imageWidth2: ref(0),
      fields: ref({} as dynamicObj),
      isSelectedAreaFieldsReady: ref(false),
      is_sep_view: ref(false),
      fuzzyDialog: ref(false),
      disableSelectionButton: ref(true),
      selectedRow: ref([]),
      tableRows: [] as dynamicObj[],
      fuzzySearchField: ref(''),
      tableColumns: [] as QTableColumn[],
      renderKey: 0,
      isReadOnly: ref(false),
    };
  },
});
</script>

