<template>
  <div
    class="image-decorator medi-selected-area-fields"
    ref="image-area"
    id="image_area"
    :style="{
      width: width + 'px',
      height: height + 'px',
    }"
  >
    <img
      @load="prepareImageData"
      id="screenshot2"
      class="original-image"
      style=""
      :src="url + '?reload=' + image_reload + '&' + tokenQueryParam"
      alt="Original Image"
      v-if="url"
      :width="width"
      :height="height"
    />

    <template v-if="!userMode">
      <div
        class=""
        id="draw"
        :style="{
          'background-color': 'rgb(0, 0, 0)',
          opacity: 0,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
        }"
        @mousedown="mouseDown"
        @mousemove="mouseMove"
      ></div>
    </template>

    <div v-for="item in areas" :key="item.id">
      <template v-if="userMode">
        <div>
          <q-input
            outlined
            :disable="isReadOnly"
            @keyup.enter="fieldKeyupEventHandler"
            :data-name="fieldsDef[item.name].name"
            :class="
              'select-areas--background_area ' +
              fieldsDef[item.name].color +
              ' ' +
              fieldsDef[item.name].name
            "
            @update:model-value="inputValueChanges(item.name)"
            v-model="local_model[item.name].formatted_value"
            :style="{
              background: `#fff url('${url}') -${item.x}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: 'move',
              width: item.width + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
            }"
          >
          </q-input>
        </div>
      </template>
      <template v-else>
        <div
          @mousedown.stop.prevent="startMove(item, $event)"
          @mousemove="doMove(item, $event)"
        >
          <div
            class="select-areas--outline"
            :style="{
              opacity: opacityOutline,
              position: 'absolute',
              cursor: 'default',
              width: item.width + 4 + 'px',
              height: item.height + 4 + 'px',
              left: areaDisplayPosX(item) - 2 + 'px',
              top: areaDisplayPosY(item) - 2 + 'px',
              'z-index': item.z,
            }"
          ></div>
          <q-input
            outlined
            class="select-areas--background_area"
            v-bind="{} as any"
            :style="{
              background: `#fff url('${url}') -${item.x}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: 'move',
              width: item.width + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
            }"
            @click="changeResizable(item.id)"
          >
            {{ item.name }}
          </q-input>
          <div
            v-if="item.resizable"
            class="delete-area"
            :style="{
              display: 'block',
              left: areaDisplayPosX(item) + item.width + 'px',
              top: areaDisplayPosY(item) - 25 + 'px',
              'z-index': item.z + 2,
            }"
            @click="deleteSelected(item.id)"
          >
            <div class="select-areas--delete_area"></div>
          </div>
          <!-- resize handler -->
          <Resizable
            :item="item"
            :posImg="posImg"
            :pos-correction="posCorrection"
            @startDrag="startDrag"
            @doDrag="doDrag"
          />
        </div>
      </template>
    </div>

    <template v-if="!userMode">
      <div
        class="c-crop--hide_main"
        :style="{
          width: width + 'px',
          height: height + 'px',
        }"
      >
        <img
          id="c-crop--hide_img"
          :src="url + '?' + tokenQueryParam"
          alt=""
          :width="width"
          :height="height"
        />
      </div>
    </template>
  </div>
</template>
<script lang="ts">
import { storeToRefs } from 'pinia';
import Resizable from './Resizable.vue';
import { SessionStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import { useImageAuth } from 'src/composables/useImageAuth';
import { $, TableCoordinateType, dynamicObj } from '../pages/assets';

let _this: any;
let tableData: dynamicObj = {
  columns: [],
  table_areas: [],
};

let imageArea: HTMLElement;
let screenshot2: HTMLElement;

export default defineComponent({
  data() {
    return {
      mousedown: false, // state mouse down event
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      areas: [] as dynamicObj[],
      latestAreaItem: { startX: 0, startY: 0, endX: 0, endY: 0 },
      scrollLeft: 0,
      scrollTop: 0,
      moveTempX: 0,
      moveTempY: 0,
      moveCurrentX: 0,
      moveCurrentY: 0,
      temp: 0,
      dragdown: false, // state mouse event drag,
      move: false,
      imageHeight: 0,
      imageWidth: 0,
      image_reload: 1,
      userMode: true,
    };
  },
  props: {
    cropUrl: {
      type: String,
      // default: 'https://scontent.fhan2-3.fna.fbcdn.net/v/t1.0-9/45585072_925043081015026_6599956628924006400_o.jpg?_nc_cat=108&_nc_oc=AQlJUcFj4S_wGeX016thVhmgINU5wDV4xPBNSCIcYSti9Sm5WEPBDYO_kxK4aRP0Emo&_nc_ht=scontent.fhan2-3.fna&oh=052bb05956a1460d014205754da5a15b&oe=5DCC1053'
      default:
        'https://dev.doc2api.cloudintegration.eu/resource/image/1b90b6d5-63b5-446b-92a4-a60d57dc0edd/1.png',
    },
    width: {
      type: Number,
      default: 1500,
    },
    height: {
      type: Number,
      default: 1500,
    },
    opacityOutline: {
      type: Number,
      default: 0.2,
    },
    opacityOverlay: {
      type: Number,
      default: 0.2,
    },
    posCorrection: {
      type: Boolean,
      default: true,
    },
    tableAreas: {
      type: String,
      default: '',
    },
    model: {} as any,
    fieldsDef: {} as any,
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    Resizable,
  },
  watch: {
    async cropUrl(val) {
      this.url = val;
      await this.setSize();
      // logInfo('cropUrl')
      this.image_reload++;
    },
    tableAreas(val) {
      // logInfo('tableAreas');
      this.image_reload++;
      this.updateLocalModel();
    },
    async width(val) {
      await this.setSize();
      //  logInfo('width', val);
      this.image_reload++;
    },
  },
  setup() {
    const { tokenQueryParam } = useImageAuth();
    return {
      local_model: ref({} as dynamicObj),
      tokenQueryParam,
    };
  },
  methods: {
    areaDisplayPosX(area: any): any {
      return area.x + (this.posCorrection ? this.posImg.left : 0);
    },
    areaDisplayPosY(area: any): any {
      return area.y + (this.posCorrection ? this.posImg.top : 0);
    },
    mousePosX(e: any) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e: any) {
      return e.pageY - this.posImg.top;
    },
    async setSize() {
      if (!this.url) {
        return;
      }
      let imgSize: any = await this.getSize(this.url);
      this.originImgSize = imgSize;
    },
    // Get the size of the src image
    getSize(src: any) {
      let img = this.$el.querySelector('#c-crop--hide_img');
      return new Promise((resolve) => {
        if (src && img) {
          img.onload = function () {
            // Compatible with unacceptable size
            const size = _this.getSizeImg(img);
            resolve(size);
          };
          img.src = src;
        } else {
          resolve({
            w: 0,
            h: 0,
            r: 0,
          });
        }
      });
    },
    getSizeImg(img: any) {
      let w = img.width;
      let h = img.height;
      let r = w === 0 && h === 0 ? 0 : w / h;
      return {
        w: w,
        h: h,
        r: r,
      };
    },
    calcPosOfBox() {
      // set posImg static
      let imageAreaRef: any = this.$refs['image-area'];

      this.scrollLeft =
        window.pageXOffset || document.documentElement.scrollLeft;
      this.scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      let imageAreaTop = imageAreaRef.getBoundingClientRect().top;
      let imageAreaLeft = imageAreaRef.getBoundingClientRect().left;

      this.posImg.top = imageAreaTop + this.scrollTop;

      this.posImg.left = imageAreaLeft + this.scrollLeft;
      // logInfo(this.posImg.top,this.posImg.left,'calcPosOfBox' );
    },
    // draw rectangle on image mouseDown mouseMove mouseUp
    mouseDown(e: any) {
      this.mousedown = true;
      let newAreaId = null;

      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }

      if (this.latestAreaItem.startX != 0 && this.latestAreaItem.startY != 0) {
        let startX = this.latestAreaItem.startX;
        let startY = this.latestAreaItem.startY;

        let endX = e.layerX;
        let endY = e.layerY;

        let width = endX - startX;
        let height = endY - startY;
        if (width < 0 || height < 0) {
          endX = startX;
          endY = startY;

          startX = e.layerX;
          startY = e.layerY;

          width = endX - startX;
          height = endY - startY;
        }

        let newArea = {
          id: newAreaId,
          x: startX,
          y: startY,
          width: width,
          height: height,
          z: 0,
          resizable: false,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
        return;
      }

      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: this.mousePosX(e),
          y: this.mousePosY(e),
          width: 0,
          height: 0,
          z: 0,
          resizable: false,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem.startX = this.mousePosX(e);
        this.latestAreaItem.startY = this.mousePosY(e);
        this.latestAreaItem.endX = 0;
        this.latestAreaItem.endY = 0;
      }
    },

    mouseMove(e: any) {
      if (this.mousedown) {
        this.areas
          .filter((x: any) => x.id === this.temp)
          .map((item: any) => {
            // if (e.pageX - item.x < 0 || e.pageY - item.y < 0) {
            //   item.width = 50
            //   item.height = 50
            // } else {
            item.width = e.pageX - item.x - this.posImg.left - 8;
            item.height = e.pageY - item.y - this.posImg.top - 8;

            // this.latestAreaItem.endX = e.pageX - this.posImg.left - 8;
            // this.latestAreaItem.endY = e.pageY - this.posImg.top - 8;
            //}
          });
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
      }
    },

    mouseUp() {
      this.mousedown = false;
      // delete all point width is = 0
      this.areas = this.areas.filter(
        (item: any) => item.width >= 3 && item.height >= 3,
      );
      this.endMove();
      this.endDrag();
      // this.setTableAreas();
      this.prepareTableArea();
    },

    // after click rectangle area select active resizable and dragable
    changeResizable(id: any) {
      this.areas
        .filter((item: any) => item.id === id)
        .map((item: any) => {
          item.resizable = true;
          item.z = 100;
        });
      this.areas
        .filter((item: any) => item.id !== id)
        .map((item: any) => {
          item.resizable = false;
          item.z = 0;
        });
    },

    // delete item area
    deleteSelected(id: any) {
      this.areas = this.areas.filter((item: any) => item.id !== id);
      this.prepareTableArea();
    },

    // drag point around rectangle on image startDrag doDrag endDrag
    startDrag() {
      this.dragdown = true;
    },

    doDrag(item: any, type: any, e: any) {
      if (this.dragdown) {
        switch (type) {
          case 'w':
            // fix drag outside box w position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'sw':
            // fix drag outside box sw position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 's':
            // fix drag outside box s position
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'se':
            // fix drag outside box se position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'e':
            // fix drag outside box e position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'ne':
            // fix drag outside box ne position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'n':
            // fix drag outside box n position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'nw':
            // fix drag outside box nw position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          default:
            break;
        }
      }
    },

    endDrag() {
      this.dragdown = false;
    },

    // move rectangle area startMove doMove endMove
    startMove(item: any, e: any) {
      this.move = true;
      this.moveTempX = e.clientX;
      this.moveTempY = e.clientY;
      this.moveCurrentX = item.x;
      this.moveCurrentY = item.y;
    },

    doMove(item: any, e: any) {
      if (this.move) {
        let x = this.moveCurrentX + (e.clientX - this.moveTempX);
        let y = this.moveCurrentY + (e.clientY - this.moveTempY);
        let maxX = this.originImgSize.w - item.width;
        let maxY = this.originImgSize.h - item.height;
        if (x > 0 && y > 0 && x < maxX && y < maxY) {
          item.x = x;
          item.y = y;
        }
      }
    },

    endMove() {
      this.move = false;
    },

    // send data from child to parent $emit
    // getListAreas () {
    //   this.$emit('getListAreas', this.areas);
    // },
    // this function only creats a test overlay reactangle. just to understand what data is expexted to creat corret overlay
    creatReactangle(
      x: number,
      y: number,
      width: number,
      height: number,
      name: string,
      fieldDef: any,
    ) {
      let newAreaId = null;
      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }
      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: x,
          y: y,
          width: width,
          height: height,
          z: 0,
          resizable: false,
          name: name,
          fieldDef: fieldDef,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
      }
    },
    prepareImageData() {
      screenshot2 = $('#screenshot2') as HTMLElement;
      if (screenshot2) {
        this.imageWidth = screenshot2.offsetWidth;
        this.imageHeight = screenshot2.offsetHeight;

        // let container = $('#image_container2') as HTMLElement;
        // logInfo('prepareImageData image', this.imageWidth, this.imageHeight);
        // logInfo('prepareImageData container',container.offsetWidth,container.offsetHeight);

        this.prepareDataForAreas();
        const event = new CustomEvent('reload_tables', {});
        document.dispatchEvent(event);
      }
    },
    prepareDataForAreas() {
      let tableData = {} as dynamicObj;
      if (
        SessionStorage.has('table_data') &&
        SessionStorage.getItem('table_data') != null &&
        SessionStorage.getItem('table_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_data');
        tableData = JSON.parse(tableDataStr as string);
      } else {
        tableData = { columns: [], table_areas: [] };
      }
      //logInfo('prepareDataForAreas', tableData, this.imageWidth, this.imageHeight);
      this.areas = [];
      let tableRect = [];

      if (!tableData.table_areas) {
        return;
      }
      for (const key in tableData.table_areas) {
        let field = tableData.table_areas[key];
        let tableRect = [];
        tableRect = field.coordinates.split(',');

        let startX = Math.round(this.imageWidth * tableRect[0]);
        let startY = Math.round(this.imageHeight * tableRect[1]);
        let endX = Math.round(this.imageWidth * tableRect[2]);
        let endY = Math.round(this.imageHeight * tableRect[3]);

        let width = endX - startX;
        let height = endY - startY;

        //  logInfo(startX, startY, width, height , field.name)

        this.creatReactangle(startX, startY, width, height, field.name, field);
      }
    },
    getTableAreaAsString(
      startX: number,
      startY: number,
      endX: number,
      endY: number,
    ): string {
      let x1 = startX / this.imageWidth;
      let y1 = startY / this.imageHeight;
      let x2 = endX / this.imageWidth;
      let y2 = endY / this.imageHeight;

      return (
        x1.toString() +
        ',' +
        y1.toString() +
        ',' +
        x2.toString() +
        ',' +
        y2.toString()
      );
    },
    prepareTableArea() {
      tableData.table_areas = [];
      Array.from(this.areas).forEach((data: any) => {
        let endX = data.width + data.x;
        let endY = data.height + data.y;

        data.fieldDef.coordinates = this.getTableAreaAsString(
          data.x,
          data.y,
          endX,
          endY,
        );
        tableData.table_areas.push(data.fieldDef);
      });
      SessionStorage.set('table_data', JSON.stringify(tableData));
    },
    calculateLeftPosition(item: any): string {
      let left = this.areaDisplayPosX(item) + item.width;
      if (left + 50 >= this.imageWidth) {
        left = this.areaDisplayPosX(item) - 60;
      }
      return left + 'px';
    },
    calculatePositionFromTop(item: any): string {
      let top = this.areaDisplayPosY(item) - 25;
      if (top < 0) {
        top = this.areaDisplayPosY(item);
      }
      return top + 'px';
    },
    inputValueChanges(field_name: string) {
      setTimeout(() => {
        this.triggerModelUpdateEvent(field_name);
      }, 0);
    },
    triggerModelUpdateEvent(field_name: string) {
      const event = new CustomEvent('model_updated', {
        detail: { field_name: field_name },
      });
      document.dispatchEvent(event);
    },
    updateLocalModel() {
      this.local_model = this.model;
    },
    fieldKeyupEventHandler(event: any) {
      if (this.userMode === false || this.isReadOnly === true) {
        return;
      }
      if (event.key === 'Enter') {
        let name = event.target.dataset.name;
        if (name) {
          this.triggerModelUpdateEvent(name);
        }
      }
    },
  },
  mounted() {
    _this = this;

    this.setSize();
    imageArea = $('#image_area') as HTMLElement;
    imageArea.addEventListener('mousemove', this.calcPosOfBox);
    imageArea.addEventListener('scroll', this.calcPosOfBox);
    this.calcPosOfBox();
    imageArea.addEventListener('mouseup', this.mouseUp);
    this.updateLocalModel();
  },
  unmounted: function () {
    imageArea.removeEventListener('mousemove', this.calcPosOfBox);
    imageArea.removeEventListener('scroll', this.calcPosOfBox);
    imageArea.removeEventListener('mouseup', this.mouseUp);
  },
});
</script>
<style lang="scss" scoped>
.c-crop {
  display: inline-block;
  * {
    box-sizing: border-box;
  }
  img {
    pointer-events: none;
  }
  .c-crop--hide_main {
    width: 0;
    height: 0;
    overflow: hidden;
  }
}

.original-image {
